import{_ as e,o as s,c as i,ao as t}from"./chunks/framework.CGAfXaNK.js";const c=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"getting_started.md","filePath":"getting_started.md","lastUpdated":null}'),n={name:"getting_started.md"};function l(p,a,h,o,r,d){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="Getting-Started" tabindex="-1">Getting Started <a class="header-anchor" href="#Getting-Started" aria-label="Permalink to &quot;Getting Started {#Getting-Started}&quot;">​</a></h1><p>In this section we install MTGeophysics.jl, check that it works, and run a first forward model and inversion on a small synthetic example. It takes about ten minutes.</p><h2 id="What-you-need" tabindex="-1">What you need <a class="header-anchor" href="#What-you-need" aria-label="Permalink to &quot;What you need {#What-you-need}&quot;">​</a></h2><ul><li><p>Julia 1.10 or newer</p></li><li><p>OpenGL, only for the interactive 3D viewers (GLMakie)</p></li><li><p>ModEM compiled with MPI, only for 3D inversion (see <a href="./inversion/3d_vfsa">3D VFSA</a>)</p></li></ul><h2 id="Install-the-package" tabindex="-1">Install the package <a class="header-anchor" href="#Install-the-package" aria-label="Permalink to &quot;Install the package {#Install-the-package}&quot;">​</a></h2><p>There are two ways to install MTGeophysics.jl. Pick the one that matches how you want to use it.</p><h3 id="Option-1:-as-a-package" tabindex="-1">Option 1: as a package <a class="header-anchor" href="#Option-1:-as-a-package" aria-label="Permalink to &quot;Option 1: as a package {#Option-1:-as-a-package}&quot;">​</a></h3><p>Use this if you want to call MTGeophysics from your own scripts. We install it into its own environment:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" class="repl-prompt repl-prompt-julia">julia</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;" class="repl-prompt repl-prompt-julia">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ]                      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># press ] to enter the package manager</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" class="repl-prompt repl-prompt-pkg">pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;" class="repl-prompt repl-prompt-pkg">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> activate </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">@mtgeophysics</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # a named environment; or \`activate .\` for the current folder</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" class="repl-prompt repl-prompt-pkg">pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;" class="repl-prompt repl-prompt-pkg">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> add MTGeophysics</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>Avoid installing packages into your default (global) Julia environment. A separate environment per project keeps versions stable and your work reproducible.</p></div><h3 id="Option-2:-from-a-clone" tabindex="-1">Option 2: from a clone <a class="header-anchor" href="#Option-2:-from-a-clone" aria-label="Permalink to &quot;Option 2: from a clone {#Option-2:-from-a-clone}&quot;">​</a></h3><p>Use this if you want the example scripts, the benchmark generators and the tests, or if you plan to change the code:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/JuliaGeophysics/MTGeophysics.jl.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MTGeophysics.jl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; Pkg.instantiate()&#39;</span></span></code></pre></div><p><code>Pkg.instantiate()</code> installs the exact versions listed in <code>Manifest.toml</code>. All commands in this documentation assume you are in the clone folder and pass <code>--project=.</code>.</p><h2 id="Check-the-installation" tabindex="-1">Check the installation <a class="header-anchor" href="#Check-the-installation" aria-label="Permalink to &quot;Check the installation {#Check-the-installation}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using MTGeophysics; println(&quot;OK&quot;)&#39;</span></span></code></pre></div><p>If this prints <code>OK</code>, you are ready to go. The first <code>using</code> compiles the package and can take a few minutes.</p><h2 id="Create-the-example-data" tabindex="-1">Create the example data <a class="header-anchor" href="#Create-the-example-data" aria-label="Permalink to &quot;Create the example data {#Create-the-example-data}&quot;">​</a></h2><p>The examples use small synthetic data sets. Let&#39;s create them:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> helpers/benchmarks_1D.jl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> helpers/benchmarks_2D.jl</span></span></code></pre></div><p>This writes two folders:</p><ul><li><p><code>examples/data/1D-I</code>: one sounding over a five-layer earth.</p></li><li><p><code>examples/data/2D-IV</code>: a 2D profile over hills with a lake, based on the COMEMI 2D-III model.</p></li></ul><p>Each folder holds the true model and noisy data computed from it. The 2D folder also holds a start model and the other inversion inputs. The control files the examples use are in <code>examples/ctrl/</code>.</p><h2 id="Your-first-run" tabindex="-1">Your first run <a class="header-anchor" href="#Your-first-run" aria-label="Permalink to &quot;Your first run {#Your-first-run}&quot;">​</a></h2><p>Now we can compute forward responses and run two inversions:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/run_fwd1D.jl</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 1D forward response</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/run_inv1D.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GN</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 1D Gauss–Newton inversion</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/run_fwd2D.jl</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 2D forward response</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/run_inv2D.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GN</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 2D Gauss–Newton inversion</span></span></code></pre></div><p>Each inversion writes a new folder, <code>run_YYYYmmdd_HHMMSS/</code>, next to the data. Inside you will find the recovered model (<code>model.rho</code>), its predicted data (<code>data.pred</code>), a short <code>Summary.txt</code> and a <code>plots/</code> folder. Open the plots to see how well the model fits the data and how it compares with the true model.</p><h2 id="Where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#Where-to-go-next" aria-label="Permalink to &quot;Where to go next {#Where-to-go-next}&quot;">​</a></h2><ul><li><p>Have your own data? Start with <a href="./data/files">Data and model files</a> and <a href="./data/mesh2d">1D and 2D meshes</a>.</p></li><li><p>Want to know what a forward run computes? See <a href="./forward/2d">Forward</a>.</p></li><li><p>Ready to invert? See <a href="./inversion/2d_deterministic">Inversion</a>.</p></li><li><p>Working in 3D? See <a href="./data/mesh3d">3D meshes</a>, <a href="./inversion/3d_vfsa">3D VFSA</a> and the <a href="./visualisation/3d_models">3D viewers</a>.</p></li></ul>`,29)])])}const g=e(n,[["render",l]]);export{c as __pageData,g as default};
